#!/usr/bin/env node

/**
 * Update Shipping Address for a Pending Order
 * 
 * This script:
 *  1. Loads orders from a local JSON "database"
 *  2. Validates the order exists, belongs to the user, and is in "pending" status
 *  3. Updates ONLY the shipping address (status remains unchanged)
 *  4. Saves the updated order back to the file
 *
 * Usage:
 *   node update_shipping_address.js
 */

const fs = require("fs");
const path = require("path");

// ─── Configuration ──────────────────────────────────────────────────────────
const DB_FILE = path.join(__dirname, "orders_db.json");

const ORDER_ID = "W4705780";
const ACCOUNT_EMAIL = "harper.collins2026@example.com";

const NEW_ADDRESS = {
  street: "4829 Elm Ridge Way, Suite 7",
  city: "Boston",
  state: "MA",
  zip: "02118",
  country: "US",
};

// ─── Helper Functions ───────────────────────────────────────────────────────

function loadOrders(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Database file not found: ${filePath}`);
  }
  const raw = fs.readFileSync(filePath, "utf-8");
  return JSON.parse(raw);
}

function saveOrders(filePath, data) {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2), "utf-8");
}

function findOrder(orders, orderId) {
  return orders.find((o) => o.orderId === orderId) || null;
}

// ─── Main Logic ─────────────────────────────────────────────────────────────

function updateShippingAddress({ orderId, email, newAddress }) {
  // 1. Load orders
  const orders = loadOrders(DB_FILE);
  console.log(`✔  Loaded ${orders.length} order(s) from database.`);

  // 2. Find the order
  const order = findOrder(orders, orderId);
  if (!order) {
    throw new Error(`Order "${orderId}" not found.`);
  }
  console.log(`✔  Found order: ${orderId}`);

  // 3. Verify account ownership
  if (order.accountEmail !== email) {
    throw new Error(
      `Email mismatch: order belongs to "${order.accountEmail}", not "${email}".`
    );
  }
  console.log(`✔  Account email verified: ${email}`);

  // 4. Check order status — only allow updates for "pending" orders
  if (order.status !== "pending") {
    throw new Error(
      `Cannot update address — order status is "${order.status}" (must be "pending").`
    );
  }
  console.log(`✔  Order status is "${order.status}" — eligible for update.`);

  // 5. Capture previous address & status for audit log
  const previousAddress = { ...order.shippingAddress };
  const statusBefore = order.status;

  // 6. Update ONLY the shipping address (status is NOT touched)
  order.shippingAddress = { ...newAddress };
  order.updatedAt = new Date().toISOString();

  // 7. Safety check — confirm status was not altered
  if (order.status !== statusBefore) {
    throw new Error("CRITICAL: Order status was unexpectedly changed. Aborting.");
  }

  // 8. Save back to database
  saveOrders(DB_FILE, orders);

  // 9. Summary
  console.log("\n══════════════════════════════════════════");
  console.log("  ADDRESS UPDATE SUCCESSFUL");
  console.log("══════════════════════════════════════════");
  console.log(`  Order:      ${orderId}`);
  console.log(`  Status:     ${order.status} (unchanged ✔)`);
  console.log(`  Previous:   ${formatAddr(previousAddress)}`);
  console.log(`  New:        ${formatAddr(order.shippingAddress)}`);
  console.log(`  Updated at: ${order.updatedAt}`);
  console.log("══════════════════════════════════════════\n");
}

function formatAddr(a) {
  return `${a.street}, ${a.city}, ${a.state} ${a.zip}, ${a.country}`;
}

// ─── Run ────────────────────────────────────────────────────────────────────
try {
  updateShippingAddress({
    orderId: ORDER_ID,
    email: ACCOUNT_EMAIL,
    newAddress: NEW_ADDRESS,
  });
} catch (err) {
  console.error(`\n✖  ERROR: ${err.message}\n`);
  process.exit(1);
}

