  // 6. Update ONLY the shipping address (status is NOT touched)
  order.shippingAddress = { ...newAddress };
  order.updatedAt = new Date().toISOString();

  // 7. Safety check — confirm status was not altered
  if (order.status !== statusBefore) {
    throw new Error("CRITICAL: Order status was unexpectedly changed. Aborting.");
  }

  // 8. Save back to database
  saveOrders(DB_FILE, orders);

  // 9. Summary
  console.log("\n══════════════════════════════════════════");
  console.log("  ADDRESS UPDATE SUCCESSFUL");
  console.log("══════════════════════════════════════════");
  console.log(`  Order:      ${orderId}`);
  console.log(`  Status:     ${order.status} (unchanged ✔)`);
  console.log(`  Previous:   ${formatAddr(previousAddress)}`);
  console.log(`  New:        ${formatAddr(order.shippingAddress)}`);
  console.log(`  Updated at: ${order.updatedAt}`);
  console.log("══════════════════════════════════════════\n");
}

function formatAddr(a) {
  return `${a.street}, ${a.city}, ${a.state} ${a.zip}, ${a.country}`;
}

// ─── Run ────────────────────────────────────────────────────────────────────
try {
  updateShippingAddress({
    orderId: ORDER_ID,
    email: ACCOUNT_EMAIL,
    newAddress: NEW_ADDRESS,
  });
} catch (err) {
  console.error(`\n✖  ERROR: ${err.message}\n`);
  process.exit(1);
}
